import cases from "./cases.json" with { type: "json" };

/**
 * One of the booklet's 57 positions, as the generated file carries it.
 * @typedef {{oll: number, name: string, image: string, group: string, steps: number, route: {auf: string, trigger: string}[], simulatorUrl: string}} Position
 */

/**
 * The booklet's 57 positions, as generated by scripts/generate-cases.mjs.
 * This module is the app's only door to that data: components never read
 * cases.json themselves.
 * @type {Position[]}
 */
export const positions = cases.positions;

/** The 14 group headings, in booklet order. */
export const groups = cases.groups;

/** @param {number} oll @returns {Position|undefined} */
export const positionOf = oll => positions.find(position => position.oll === oll);
